local QBCore = exports['qb-core']:GetCoreObject()
local heists = {}
local cooldowns, activeRuns, requestTimes, pendingInvites = {}, {}, {}, {}

local function notify(source, message, kind) TriggerClientEvent('heistcreator:client:notify', source, message, kind or 'primary') end
local function loadData() local raw=LoadResourceFile(GetCurrentResourceName(),Config.DataFile); local decoded=raw and json.decode(raw) or {}; heists=type(decoded)=='table' and decoded or {} end
local function saveData() SaveResourceFile(GetCurrentResourceName(),Config.DataFile,json.encode(heists),-1) end
local function isAdmin(source) if source==0 or IsPlayerAceAllowed(source,Config.AdminAce) then return true end; local p=QBCore.Functions.GetPlayer(source); if not p then return false end; local permission=p.PlayerData.permission or p.PlayerData.role; for _,allowed in ipairs(Config.AdminPermissions) do if permission==allowed then return true end end; return false end
local function guarded(source) if not isAdmin(source) then notify(source,'You are not authorized to use the heist creator.','error'); return false end; local now=os.time(); if requestTimes[source] and now-requestTimes[source]<1 then return false end; requestTimes[source]=now; return true end
local function findHeist(id) for index,heist in ipairs(heists) do if heist.id==id then return heist,index end end end
local function newId() return ('heist_%s_%s'):format(os.time(),math.random(100000,999999)) end
local function copy(value) return json.decode(json.encode(value)) end
local function near(source,position,distance) local ped=GetPlayerPed(source); if ped==0 then return false end; local coords=GetEntityCoords(ped); return #(coords-vector3(position.x,position.y,position.z))<=distance end
local function policeCount() local count=0; for _,playerId in ipairs(QBCore.Functions.GetPlayers()) do local p=QBCore.Functions.GetPlayer(playerId); if p and p.PlayerData.job and p.PlayerData.job.name=='police' and p.PlayerData.job.onduty then count=count+1 end end; return count end
local function participant(run, source) return run and run.members[source] == true end
local function memberCount(run) local count=0; for _ in pairs(run.members) do count=count+1 end; return count end
local function broadcastRun(run, event, ...) for playerId in pairs(run.members) do TriggerClientEvent(event, playerId, ...) end end
local function rewardPlayer(source, heist) local player=QBCore.Functions.GetPlayer(source); if not player then return end; for _,reward in ipairs(heist.rewards) do if reward.type=='cash' or reward.type=='bank' then player.Functions.AddMoney(reward.type,reward.amount,'heist-reward') else player.Functions.AddItem(reward.item,reward.amount,false,false,'heist-reward') end end; notify(source,'Heist completed. Rewards delivered.','success') end
local function clearRun(run) for playerId in pairs(run.members) do activeRuns[playerId]=nil end end
local function createRun(heist, source, test) local run={id=heist.id,next=1,expires=os.time()+3600,test=test,members={[source]=true},leader=source}; activeRuns[source]=run; return run end

RegisterNetEvent('heistcreator:server:open',function() local source=source; if not isAdmin(source) then notify(source,'You are not authorized to use the heist creator.','error'); return end; TriggerClientEvent('heistcreator:client:open',source,heists) end)
RegisterNetEvent('heistcreator:server:requestHeists',function() TriggerClientEvent('heistcreator:client:publicSync',source,heists) end)
RegisterNetEvent('heistcreator:server:save',function(payload) local source=source; if not guarded(source) then return end; local existingId=type(payload)=='table' and payload.id or nil; local valid,result=HeistSchema.validate(payload,existingId); if not valid then notify(source,result,'error'); return end; local old,index=existingId and findHeist(existingId) or nil; if not old and #heists>=Config.MaxHeists then notify(source,'The heist limit has been reached.','error'); return end; result.id=existingId or newId(); if old then heists[index]=result else heists[#heists+1]=result end; saveData(); notify(source,old and 'Heist updated.' or 'Heist created.','success'); TriggerClientEvent('heistcreator:client:sync',source,heists); TriggerClientEvent('heistcreator:client:publicSync',-1,heists) end)
RegisterNetEvent('heistcreator:server:delete',function(id) local source=source; if not guarded(source) then return end; local _,index=findHeist(tostring(id)); if not index then notify(source,'Heist not found.','error'); return end; table.remove(heists,index); saveData(); notify(source,'Heist deleted.','success'); TriggerClientEvent('heistcreator:client:sync',source,heists); TriggerClientEvent('heistcreator:client:publicSync',-1,heists) end)
RegisterNetEvent('heistcreator:server:test',function(id) local source=source; if not guarded(source) then return end; if activeRuns[source] then notify(source,'Leave your current heist before testing another.','error'); return end; local heist=findHeist(tostring(id)); if not heist then notify(source,'Heist not found.','error'); return end; createRun(heist,source,true); TriggerClientEvent('heistcreator:client:test',source,copy(heist)) end)
RegisterNetEvent('heistcreator:server:start',function(id) local source=source; local heist=findHeist(tostring(id)); local player=QBCore.Functions.GetPlayer(source); if not heist or not player then return end; if activeRuns[source] then notify(source,'You are already in a heist team.','error'); return end; if not near(source,heist.entry,Config.EntryDistance) then notify(source,'You are too far from the heist entry.','error'); return end; if heist.minCops>policeCount() then notify(source,'There are not enough police on duty.','error'); return end; local readyAt=cooldowns[source] and cooldowns[source][heist.id] or 0; if readyAt>os.time() then notify(source,('You must wait %s seconds.'):format(readyAt-os.time()),'error'); return end; cooldowns[source]=cooldowns[source] or {}; cooldowns[source][heist.id]=os.time()+heist.cooldown; createRun(heist,source,false); TriggerClientEvent('heistcreator:client:run',source,copy(heist),true,1,false) end)
RegisterNetEvent('heistcreator:server:invite',function(target) local source=source; target=tonumber(target); local run=activeRuns[source]; local heist=run and findHeist(run.id); if not run or run.leader~=source or not heist then return end; if run.test then notify(source,'Team invitations are disabled in test mode.','error'); return end; if memberCount(run)>=(heist.maxParticipants or 1) then notify(source,'The team is full.','error'); return end; if not target or not GetPlayerName(target) or target==source then notify(source,'Invalid participant.','error'); return end; if activeRuns[target] then notify(source,'That player is already in a heist team.','error'); return end; if not near(source,heist.entry,Config.InviteDistance) or not near(target,heist.entry,Config.InviteDistance) then notify(source,'Both players must be near the heist entry.','error'); return end; pendingInvites[target]={run=run,expires=os.time()+30}; notify(source,'Invitation sent.','success'); TriggerClientEvent('heistcreator:client:invite',target,heist.name,source) end)
RegisterNetEvent('heistcreator:server:respondInvite',function(accept) local source=source; local invite=pendingInvites[source]; pendingInvites[source]=nil; if not invite or invite.expires<os.time() or accept~=true then if invite and invite.run.leader then notify(invite.run.leader,'Invitation declined or expired.','error') end; return end; local run=invite.run; local heist=findHeist(run.id); if activeRuns[run.leader]~=run or run.expires<os.time() or not heist or activeRuns[source] or memberCount(run)>=(heist.maxParticipants or 1) or not near(source,heist.entry,Config.InviteDistance) then notify(source,'This team invitation is no longer available.','error'); return end; run.members[source]=true; activeRuns[source]=run; TriggerClientEvent('heistcreator:client:run',source,copy(heist),false,run.next,run.test); notify(source,'You joined the heist team.','success'); notify(run.leader,('%s joined your team.'):format(GetPlayerName(source))) end)
RegisterNetEvent('heistcreator:server:leave',function() local source=source; local run=activeRuns[source]; if not run then return end; if run.leader==source then broadcastRun(run,'heistcreator:client:teamEnded','The team leader left the heist.'); clearRun(run) else run.members[source]=nil; activeRuns[source]=nil; notify(source,'You left the heist team.','success') end end)
RegisterNetEvent('heistcreator:server:objective',function(id,index) local source=source; local run=activeRuns[source]; local heist=findHeist(tostring(id)); if not participant(run,source) or run.id~=id or run.expires<os.time() or run.next~=tonumber(index) or not heist then return end; local objective=heist.objectives[run.next]; if not objective or not near(source,objective.position,Config.InteractionDistance+1.5) then return end; run.next=run.next+1; broadcastRun(run,'heistcreator:client:objectiveAccepted',run.next-1) end)
RegisterNetEvent('heistcreator:server:complete',function(id) local source=source; local run=activeRuns[source]; local heist=findHeist(tostring(id)); if not participant(run,source) or run.leader~=source or not heist or run.id~=id or run.expires<os.time() or run.next<=#heist.objectives or not near(source,heist.entry,Config.EntryDistance) then return end; local wasTest=run.test; local members={}; for playerId in pairs(run.members) do members[#members+1]=playerId end; broadcastRun(run,'heistcreator:client:teamEnded',wasTest and 'Test heist completed.' or 'Heist completed by the team leader.'); clearRun(run); if wasTest then notify(source,'Test heist completed. Rewards were disabled.','success'); return end; for _,playerId in ipairs(members) do rewardPlayer(playerId,heist) end end)
AddEventHandler('playerDropped',function() local source=source; local run=activeRuns[source]; if run and run.leader==source then broadcastRun(run,'heistcreator:client:teamEnded','The team leader disconnected.'); clearRun(run) elseif run then run.members[source]=nil; activeRuns[source]=nil end; requestTimes[source]=nil; cooldowns[source]=nil; pendingInvites[source]=nil end)
exports('GetHeist',function(id) return findHeist(id) end); exports('GetHeists',function() return heists end); math.randomseed(os.time()); loadData()
